<?php
declare(strict_types=1);
require_once __DIR__.'/lib/bootstrap.php';
$ref=preg_replace('/[^a-f0-9]/','',strtolower((string)($_GET['ref']??'')));
$order=null;$jobs=[];$items=[];
if(strlen($ref)===32){
 try{$pdo=db();$s=$pdo->prepare('SELECT order_ref,status,items_json,created_at,paid_at FROM orders WHERE order_ref=? LIMIT 1');$s->execute([$ref]);$order=$s->fetch();
  if($order){$items=json_decode($order['items_json'],true)?:[];$s=$pdo->prepare('SELECT provider,status,tracking_number,tracking_url,updated_at FROM fulfillment_jobs WHERE order_ref=? ORDER BY id');$s->execute([$ref]);$jobs=$s->fetchAll();}
 }catch(Throwable $e){error_log('Order tracking: '.$e->getMessage());}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track your HSW365 order</title><link rel="stylesheet" href="/assets/store.css"></head><body><main style="max-width:760px;margin:8vh auto;padding:28px"><a class="brand" href="/"><span>HSW</span><b>365</b></a><p class="eyebrow" style="margin-top:48px">ORDER TRACKING</p><?php if(!$order): ?><h1 style="font-size:42px">We couldn't find that order.</h1><p>Use the private tracking link from your order confirmation.</p><?php else: ?><h1 style="font-size:42px">Your order status</h1><p>Reference: <strong><?=htmlspecialchars($ref,ENT_QUOTES)?></strong></p><p>Status: <strong><?=htmlspecialchars(str_replace('_',' ',$order['status']),ENT_QUOTES)?></strong></p><h2>Items</h2><?php foreach($items as $item): ?><p><?=htmlspecialchars($item['title']??'Item',ENT_QUOTES)?> — <?=htmlspecialchars($item['variant_title']??'',ENT_QUOTES)?> × <?=htmlspecialchars((string)($item['quantity']??1),ENT_QUOTES)?></p><?php endforeach; ?><h2>Shipping updates</h2><?php if(!$jobs): ?><p>Tracking information will appear here when your order is processed.</p><?php else: foreach($jobs as $job): ?><div class="admin-row"><strong><?=htmlspecialchars($job['provider'],ENT_QUOTES)?></strong> · <?=htmlspecialchars(str_replace('_',' ',$job['status']),ENT_QUOTES)?><?php if($job['tracking_number']): ?><p>Tracking: <?=htmlspecialchars($job['tracking_number'],ENT_QUOTES)?></p><?php endif; ?><?php if($job['tracking_url']): ?><p><a href="<?=htmlspecialchars($job['tracking_url'],ENT_QUOTES)?>" target="_blank" rel="noopener noreferrer">Open carrier tracking</a></p><?php endif; ?></div><?php endforeach; endif; ?><?php endif; ?><a class="primary-link" href="/">Back to HSW365 <span>↗</span></a></main></body></html>